// The town on the ground (docs/town.md, docs/art/town-brief.md): where the layout generated by the Blender build
// (scenes/town-data.js, town-local metres) meets the client. Pure data and helpers, no three.js, so the rules are
// checked by node tests like scenes/layout.js. Nothing here repeats a number of TOWN_DATA: that file is regenerated.
//
// The town lives in the same THREE.Scene as the archipelago, far away at TOWN_ORIGIN, with its own collision world
// (the precedent is the Shell interior at SHELL_ORIGIN, scenes/shell.js). The archipelago sits at the origin, the
// Shell interior at [0, 300, 0] and the camera far plane is 500 m, so neither place ever sees the other.
import { TOWN_DATA } from './town-data.js';
import { OUTSIDE_KILL_Y } from './town-outside.js';

export { TOWN_DATA };

/** World position of the town's local origin. */
export const TOWN_ORIGIN = Object.freeze([0, 1200, 0]);

/** Town-local point -> world. */
export const townToWorld = (p) => [p[0] + TOWN_ORIGIN[0], p[1] + TOWN_ORIGIN[1], p[2] + TOWN_ORIGIN[2]];
/** World point -> town-local. */
export const townToLocal = (p) => [p[0] - TOWN_ORIGIN[0], p[1] - TOWN_ORIGIN[1], p[2] - TOWN_ORIGIN[2]];

/** Heading (CharacterController: 0 faces +Z) that looks from `from` toward `to` on the ground plane. */
export const headingToward = (from, to) => Math.atan2(to[0] - from[0], to[2] - from[2]);

/**
 * Where Iris starts: inside the lower gate. The plan's point stands right in front of the gate arch, where the
 * arch pushed the follow camera into her back (she was cut at the hips); she starts a few steps up the street
 * instead, so the camera has its full distance behind her and the first frame shows her whole with the street ahead.
 */
export const SPAWN_ADVANCE = 4.5;
export const TOWN_SPAWN = (() => {
  const h = TOWN_DATA.spawn.heading, p = TOWN_DATA.spawn.position;
  return Object.freeze({ position: Object.freeze(townToWorld([p[0] + Math.sin(h) * SPAWN_ADVANCE, p[1], p[2] + Math.cos(h) * SPAWN_ADVANCE])), heading: h });
})();

/** The Tournament altar in world space: its pivot, the spot where Iris stands, the camera focus, the prompt radius. */
export const TOWN_ALTAR = Object.freeze({
  position: Object.freeze(townToWorld(TOWN_DATA.altar.position)),
  stand: Object.freeze(townToWorld(TOWN_DATA.altar.stand)),
  focus: Object.freeze(townToWorld(TOWN_DATA.altar.focus)),
  radius: TOWN_DATA.altar.radius,
});

/** Dev spawn at the altar stand, facing the altar (?town=altar, QA screenshots). */
export const TOWN_ALTAR_SPAWN = Object.freeze({ position: TOWN_ALTAR.stand, heading: headingToward(TOWN_DATA.altar.stand, TOWN_DATA.altar.position) });

/** Centre line of the jury walk, world space (ground points from the spawn to the altar stand). */
export const TOWN_ROUTE = Object.freeze(TOWN_DATA.route.map((p) => Object.freeze(townToWorld(p))));

/** Length of a polyline in metres (3D: the steps and ramps count). */
export function routeLength(points) {
  let d = 0;
  for (let i = 1; i < points.length; i++) d += Math.hypot(points[i][0] - points[i - 1][0], points[i][1] - points[i - 1][1], points[i][2] - points[i - 1][2]);
  return d;
}
export const TOWN_ROUTE_LENGTH = routeLength(TOWN_DATA.route);

/**
 * Below this world height Iris respawns at her last safe point (CharacterController.killY is absolute). The plan's
 * kill height sits under the streets; the hillside beyond the gate runs much lower (scenes/town-outside.js).
 */
export const TOWN_KILL_Y = TOWN_ORIGIN[1] + Math.min(TOWN_DATA.killY, OUTSIDE_KILL_Y);

/** Height fog base in the town: mist pools below the hill (render/fog.js; the archipelago uses its cloud level). */
export const TOWN_FOG_BASE_Y = TOWN_ORIGIN[1] - 20;
/** The cloud sea moves here while Iris is in the town: a sea of mist around the hill, below every walkable level. */
export const TOWN_MIST_LEVEL = TOWN_ORIGIN[1] - 32;

/** The town's atmosphere floor (LookDev.setAtmosphereFloor). Fog colour, exposure and grading belong to the look-dev lane. */
export const TOWN_ATMOSPHERE = Object.freeze({ fogBaseY: TOWN_FOG_BASE_Y, mistLevel: TOWN_MIST_LEVEL });

/**
 * The camera in the streets: a low, close third-person view (the archipelago's 30 m isometric overview would sit
 * inside the houses and show only cobbles). `tilt` is added to the rig's zoom-tied pitch (about 19 degrees at this
 * distance, so about 11 above the horizontal); `minPitch` lets the player tilt below the horizontal to look up at
 * the dome and the islands in the sky (about 30 degrees up); the rig's own 8 degrees return on leaving.
 */
// `far`: the islands in the sky reach past the archipelago's 500 m far plane (the archipelago itself is 1200 m away).
export const TOWN_CAMERA = Object.freeze({ dist: 6.5, tilt: -0.14, minPitch: -16 * Math.PI / 180, far: 900 });

/** The sky piece's bounding sphere in world space (the archipelago seen from below), or null without one. */
export const TOWN_SKY = (() => {
  const p = TOWN_DATA.pieces.find((x) => x.kind === 'town_sky');
  return p ? Object.freeze({ center: Object.freeze(townToWorld(p.center)), radius: p.radius }) : null;
})();

/** Camera rig yaw that looks from a world position toward a world point (the rig sits on the far side of its focus). */
export const yawToward = (from, to) => Math.atan2(from[0] - to[0], from[2] - to[2]);

/** Kinds a town piece may have (render/asset-catalog.js lists the same keys in LOAD_DISTANCE and TRIANGLE_BUDGET). */
export const TOWN_KINDS = Object.freeze(['town_terrain', 'town_block', 'town_hero', 'town_sky']);

/** The piece that carries the ground: Iris is held at the spawn until it is real. */
export const TOWN_TERRAIN = 'town_terrain';
export const TOWN_ALTAR_ASSET = 'town_altar';

/** Placed pieces in world space. `visualOnly`: no collision is expected (the sky impostor of the archipelago). */
export const TOWN_PIECES = Object.freeze(TOWN_DATA.pieces.map((p) => Object.freeze({
  name: p.name, kind: p.kind, position: Object.freeze(townToWorld(p.position)), visualOnly: p.kind === 'town_sky',
})));

/**
 * The dev flat ground (?town=flat, and the fallback when the build has no terrain file): one box under the whole
 * playable area with its top at the spawn height. Returns world-space [min, max].
 */
export function townFlatGround() {
  const [w, d] = TOWN_DATA.size;
  const top = TOWN_SPAWN.position[1];
  return { min: [TOWN_ORIGIN[0] - w / 2, top - 1, TOWN_ORIGIN[2] - d / 2], max: [TOWN_ORIGIN[0] + w / 2, top, TOWN_ORIGIN[2] + d / 2], top };
}

/** Ground distance from a world position to the altar pivot. */
export function altarDistance(pos) { return Math.hypot(pos[0] - TOWN_ALTAR.position[0], pos[2] - TOWN_ALTAR.position[2]); }

/** Whether the registration prompt is offered at this world position. */
export function inAltarRange(pos) { return altarDistance(pos) <= TOWN_ALTAR.radius; }

/**
 * How awake the altar's amber core is, 0..1, from Iris's ground distance: asleep beyond 2.5 radii, fully awake at
 * the prompt radius, a smooth ease between.
 */
export function altarWake(distance, radius = TOWN_ALTAR.radius) {
  const far = radius * 2.5;
  const t = Math.min(1, Math.max(0, (far - distance) / (far - radius)));
  return t * t * (3 - 2 * t);
}

/* ---------------- shops: walk-in interiors (docs/town.md "Shops") ---------------- */

/**
 * Where the shop interiors live: far beside the town in the same THREE.Scene (the Shell interior at SHELL_ORIGIN is
 * the precedent), one every SHOP_SPACING metres along +X, each with its own collision world (scenes/town-shops.js).
 * 2 km is beyond every camera far plane, so no room is ever seen from the town or the archipelago, or from another room.
 */
export const SHOP_ORIGIN_BASE = Object.freeze([TOWN_ORIGIN[0] + 2000, TOWN_ORIGIN[1], TOWN_ORIGIN[2]]);
export const SHOP_SPACING = 200;
export const TOWN_INTERIOR_KIND = 'town_interior';

/**
 * Light inside a shop (tuned from screenshots; the only place these numbers live). The interiors carry their light
 * baked into vertex colour, so indoors the sun, the sky fill, the environment map, fog, mist, clouds, rain, wetness
 * and sun shafts are all off (LookDev.setInterior) and the room is lit by:
 *   ambient   one neutral white AmbientLight. Math.PI makes a vertex colour of 1.0 show the unlit albedo of a
 *             dielectric (three.js divides Lambert by pi) before tone mapping;
 *   exposure  stops (EV) for the tone mapping while indoors: 0 is exposure 1.0, whatever the hour and weather outside;
 *   lamp      up to `max` warm point lights without shadows at the room's `socket_lamp_*` empties nearest Iris
 *             (tiers with `pointLights` only), so she and the speculars feel lit: intensity (cd), reach (m), colour.
 */
export const SHOP_LIGHT = Object.freeze({
  ambient: Math.PI,
  exposure: 0,
  lamp: Object.freeze({ intensity: 5, distance: 9, color: 0xffb070, max: 6 }),
});

/**
 * The camera in a 9 x 11 m room under a 3.6 m ceiling: close behind Iris and nearly level, so it stays under the
 * beams; the rig's sphere sweep against the room's own colliders keeps it out of the walls. `pitch` is the angle
 * above the horizontal at `dist` (the rig's zoom-tied pitch is cancelled); zoom is limited to minDist..maxDist.
 */
export const SHOP_CAMERA = Object.freeze({ dist: 4.2, minDist: 2.4, maxDist: 6.5, pitch: 5 * Math.PI / 180, minPitch: -10 * Math.PI / 180 });

/**
 * Seconds of the door transition: fade to dark and back (`reducedFade` under reduced motion: a plain short
 * cross-fade, no camera push), the longest wait for a room to stream in (or for the street to come back) before the
 * door gives up, how long a shopkeeper's line stays, and how near a door (m) the room's file is put into the HTTP cache.
 */
export const SHOP_TRANSITION = Object.freeze({ fade: 0.45, reducedFade: 0.2, wait: 25, line: 7, prefetch: 9, push: 1.2 });

/** Who keeps each shop and what talking to them opens, until scenes/town-data.js carries `keeper` and `opens` itself. */
const SHOP_KEEPERS = Object.freeze({ exchange: 'maren', scribe: 'odo', inn: 'bram' });
const SHOP_OPENS = Object.freeze({ exchange: 'shards', scribe: 'dictionary', inn: null });
/** What a counter may open: the Memories panel (shards), Iris's dictionary book, or nothing (a line of talk). */
export const SHOP_VIEWS = Object.freeze(['shards', 'dictionary']);

const add3 = (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];

/** Where Iris stands after leaving: `back` metres out of the door point, facing away from the door. */
export function shopStreetReturn(door, back = 0.6) {
  const h = door.heading; // the direction she faces walking in
  return { position: [door.position[0] - Math.sin(h) * back, door.position[1], door.position[2] - Math.cos(h) * back], heading: h + Math.PI };
}

/**
 * One shop of the data in world space. `door` is on the street (town world); `origin` is where the interior file is
 * placed; `spawn`, `exit`, `counter`, `keeperStand` are inside (interior-local + origin) and are replaced by the
 * file's own empties when it has them. `street` is where Iris returns to.
 */
export function shopFromData(s, index) {
  const origin = [SHOP_ORIGIN_BASE[0] + index * SHOP_SPACING, SHOP_ORIGIN_BASE[1], SHOP_ORIGIN_BASE[2]];
  const it = s.interior || {};
  const size = it.size || [9, 3.6, 11];
  const pt = (p, fallback) => add3(origin, (p && p.position) || fallback);
  const opens = 'opens' in s ? s.opens : (s.id in SHOP_OPENS ? SHOP_OPENS[s.id] : null);
  const door = { position: townToWorld(s.door.position), heading: s.door.heading, radius: s.door.radius ?? 1.6 };
  return Object.freeze({
    id: s.id, index, piece: s.piece,
    keeper: s.keeper || SHOP_KEEPERS[s.id] || null,
    opens: SHOP_VIEWS.includes(opens) ? opens : null,
    origin: Object.freeze(origin), size: Object.freeze(size.slice()),
    door: Object.freeze(door), street: Object.freeze(shopStreetReturn(door)),
    spawn: Object.freeze({ position: pt(it.spawn, [0, 0, size[2] / 2 - 1.2]), heading: (it.spawn && it.spawn.heading) ?? Math.PI }),
    exit: Object.freeze({ position: pt(it.exit, [0, 0, size[2] / 2 - 0.5]), radius: (it.exit && it.exit.radius) ?? 1.1 }),
    counter: Object.freeze({ position: pt(it.counter, [0, 0, -2]), radius: (it.counter && it.counter.radius) ?? 1.8 }),
    keeperStand: Object.freeze({ position: pt(it.shopkeeper_stand, [0, 0, -4]), heading: (it.shopkeeper_stand && it.shopkeeper_stand.heading) ?? 0 }),
    killY: origin[1] - 10,
  });
}

/** Town spots without a model of their own, in town-local metres: the notice board after the stairs, the mirror by the gate. */
export const TOWN_SPOTS = Object.freeze({ board: Object.freeze([1.6, 2.5, 4.0]), mirror: Object.freeze([2.0, 0, 21.5]) });

/** The shops Iris can walk into (empty when the data has none). */
export const TOWN_SHOPS = Object.freeze((TOWN_DATA.shops || []).map(shopFromData));
export const shopById = (id, shops = TOWN_SHOPS) => shops.find((s) => s.id === id) || null;

/** The shop whose street door Iris stands at (ground distance inside the door radius, on the same level), or null. */
export function shopDoorAt(pos, shops = TOWN_SHOPS) {
  let best = null, bestD = Infinity;
  for (const s of shops) {
    const d = Math.hypot(pos[0] - s.door.position[0], pos[2] - s.door.position[2]);
    if (d <= s.door.radius && Math.abs(pos[1] - s.door.position[1]) <= 2 && d < bestD) { best = s; bestD = d; }
  }
  return best;
}

/** Inside a shop: 'counter' (the customer side of the counter), 'exit' (at the door) or null. The counter wins a tie. */
export function shopZoneAt(points, pos) {
  const within = (z) => !!z && Math.hypot(pos[0] - z.position[0], pos[2] - z.position[2]) <= z.radius;
  return within(points.counter) ? 'counter' : within(points.exit) ? 'exit' : null;
}

/** Phases of a shop visit, in order (scenes/town-shops.js). */
export const SHOP_PHASES = Object.freeze(['street', 'entering', 'inside', 'talking', 'leaving']);

/**
 * The one prompt a moment offers: enter at a street door, talk at the counter, leave at the interior door; nothing
 * during a fade or while a view is open. Returns `{action, key, fallback}`: `key` is the locale key for this shop or
 * keeper, `fallback` the generic one for a shop or keeper the locales do not name yet.
 * @param {{phase: string, near?: object|null, shop?: object|null, zone?: string|null}} s
 */
export function shopPrompt({ phase, near = null, shop = null, zone = null }) {
  if (phase === 'street') return near ? { action: 'enter', key: 'town.shop.enter.' + near.id, fallback: 'town.shop.enter' } : null;
  if (phase !== 'inside' || !shop) return null;
  if (zone === 'counter') return { action: 'talk', key: 'town.shop.talk.' + (shop.keeper || 'keeper'), fallback: 'town.shop.talk' };
  if (zone === 'exit') return { action: 'leave', key: 'town.shop.leave', fallback: 'town.shop.leave' };
  return null;
}
